    80→	}
    81→
    82→	/**
    83→	 * Reads a specified number of bytes into an array at the specified offset with control over whether the read should be
    84→	 * buffered (callers who have their own buffer should pass in "false" for useBuffer). Currently only
    85→	 * {@link BufferedIndexInput} respects this parameter.
    86→	 * 
    87→	 * @param b
    88→	 *            the array to read bytes into
    89→	 * @param offset
    90→	 *            the offset in the array to start storing bytes
    91→	 * @param len
    92→	 *            the number of bytes to read
    93→	 * @param useBuffer
    94→	 *            set to false if the caller will handle buffering.
    95→	 * @see IndexOutput#writeBytes(byte[],int)
    96→	 */
    97→	public void readBytes(byte[] b, int offset, int len, boolean useBuffer) throws IOException {
    98→		// Default to ignoring useBuffer entirely
    99→		readBytes(b, offset, len);
   100→	}
   101→
   102→	/**
   103→	 * Reads two bytes and returns a short.
   104→	 * 
   105→	 * @see IndexOutput#writeByte(byte)
   106→	 */
   107→	public short readShort() throws IOException {
