        while ((value and 0x7FL.inv()) != 0L) {
            writeByte(((value and 0x7FL) or 0x80L).toByte())
            value = value ushr 7
        }
        writeByte(value.toByte())
    }

    private var copyBuffer: ByteArray? = null

    @Throws(IOException::class)
    fun copyBytes(input: DataInput, numBytes: Long) {
        assert(numBytes >= 0) { "numBytes=$numBytes" }
        var left = numBytes
        if (copyBuffer == null) {
            copyBuffer = ByteArray(COPY_BUFFER_SIZE)
        }
        while (left > 0) {
            val toCopy: Int = if (left > COPY_BUFFER_SIZE) {
                COPY_BUFFER_SIZE
            } else {
                left.toInt()
            }
            input.readBytes(copyBuffer!!, 0, toCopy)
            writeBytes(copyBuffer!!, 0, toCopy)
            left -= toCopy
        }
    }

    @Throws(IOException::class)
    fun writeStringStringMap(map: Map<String, String>?) {
        if (map == null) {
            writeInt(0)
        } else {
            writeInt(map.size)
            for ((key, value) in map) {
                writeString(key)
                writeString(value)
            }
        }
    }

    @Throws(IOException::class)
    fun writeStringSet(set: Set<String>?) {
        if (set == null) {
            writeInt(0)
        } else {
            writeInt(set.size)
            for (value in set) {
                writeString(value)
            }
        }
    }

    @Throws(IOException::class)
    fun writeUTF8String(str: String) {
        val charCount = str.length
        writeVInt(charCount)
        for (i in 0 until charCount) {
            val c = str[i].code
            if (c <= 0x007F) {
                writeByte(c.toByte())
            } else if (c > 0x07FF) {
                writeByte((0xE0 or (c shr 12 and 0x0F)).toByte())
                writeByte((0x80 or (c shr 6 and 0x3F)).toByte())
                writeByte((0x80 or (c shr 0 and 0x3F)).toByte())
            } else {
                writeByte((0xC0 or (c shr 6 and 0x1F)).toByte())
                writeByte((0x80 or (c shr 0 and 0x3F)).toByte())
            }
        }
    }

    @Throws(IOException::class)
    fun writeAString(str: String?) {
        val s = str ?: ""
        writeAString(s.toCharArray(), 0, s.length)
    }

    @Throws(IOException::class)
    fun writeString(str: String?) {
        val s = str ?: ""
        writeUString(s.toCharArray(), 0, s.length)
    }

    @Throws(IOException::class)
    fun writeFloat(v: Float) {
        writeInt(java.lang.Float.floatToIntBits(v))
    }

    @Throws(IOException::class)
    fun writeDouble(v: Double) {
        writeLong(java.lang.Double.doubleToLongBits(v))
    }

    @Throws(IOException::class)
    fun writeBoolean(b: Boolean) {
        writeByte(if (b) ONE else ZERO)
    }

    @Throws(IOException::class)
    @JvmOverloads
    fun writeAChar(v: Int, upperCase: Boolean = false) {
        var value = v
        if (upperCase && value in 97..122) {
            value -= 32
        }
        writeByte(value.toByte())
    }

    @Throws(IOException::class)
    @JvmOverloads
    fun writeUChar(v: Int, upperCase: Boolean = false) {
        var value = v
        if (upperCase && value in 97..122) {
            value -= 32
        }
        writeShort(value.toShort())
    }

    @Throws(IOException::class)
    fun writeAString(v: CharArray, start: Int, length: Int) {
        writeVInt(length)
        writeAChars(v, start, length)
    }

    @Throws(IOException::class)
    fun writeUString(v: CharArray, start: Int, length: Int) {
        writeVInt(length * 2)
        writeUChars(v, start, length)
    }

    @Throws(IOException::class)
    @JvmOverloads
    fun writeAChars(v: CharArray, start: Int, length: Int, upperCase: Boolean = false) {
        if (length == 0) return
        var newLength = length
        if (v.isNotEmpty()) {
            if (start >= v.size) {
                throw IOException("start position exceeds array length. start=$start, array.length=${v.size}")
            }
            if (start + length > v.size) {
                newLength = v.size - start
            }
            for (i in 0 until newLength) {
                writeAChar(v[start + i].code, upperCase)
            }
        } else {
            newLength = 0
        }
        for (i in 0 until length - newLength) {
            writeAChar(0)
        }
    }

    @Throws(IOException::class)
    @JvmOverloads
    fun writeUChars(v: CharArray, start: Int, length: Int, upperCase: Boolean = false) {
        if (length == 0) return
        var newLength = length
        if (v.isNotEmpty()) {
            if (start >= v.size) {
                throw IOException("start position exceeds array length. start=$start, array.length=${v.size}")
            }
            if (start + length > v.size) {
                newLength = v.size - start
            }
            for (i in 0 until newLength) {
                writeUChar(v[start + i].code, upperCase)
            }
        } else {
            newLength = 0
        }
        for (i in 0 until length - newLength) {
            writeUChar(0)
        }
    }

    @Throws(IOException::class)
    fun writeStringArray(array: Array<String>) {
        writeVInt(array.size)
        for (s in array) {
            writeString(s)
        }
    }

    @Throws(IOException::class)
    fun writeStringArrayNullable(array: Array<String>?) {
        if (array == null) {
            writeVInt(0)
        } else {
            writeVInt(array.size)
            for (s in array) {
                writeString(s)
            }
        }
    }

    @Throws(IOException::class)
    fun writeMap(map: Map<String, Any>) {
        writeGenericValue(map)
    }

    @Throws(IOException::class)
    fun writeGenericValue(value: Any?) {
        if (value == null) {
            writeByte((-1).toByte())
            return
        }
        val type = value.javaClass
        when {
            type == String::class.java -> {
                writeByte(0.toByte())
                writeString(value as String)
            }
            type == Int::class.javaObjectType || type == java.lang.Integer::class.java -> {
                writeByte(1.toByte())
                writeInt(value as Int)
            }
            type == Long::class.javaObjectType || type == java.lang.Long::class.java -> {
                writeByte(2.toByte())
                writeLong(value as Long)
            }
            type == Float::class.javaObjectType || type == java.lang.Float::class.java -> {
                writeByte(3.toByte())
                writeFloat(value as Float)
            }
            type == Double::class.javaObjectType || type == java.lang.Double::class.java -> {
                writeByte(4.toByte())
                writeDouble(value as Double)
            }
            type == Boolean::class.javaObjectType || type == java.lang.Boolean::class.java -> {
                writeByte(5.toByte())
                writeBoolean(value as Boolean)
            }
            type == ByteArray::class.java -> {
                writeByte(6.toByte())
                writeVInt((value as ByteArray).size)
                writeBytes(value)
            }
            value is List<*> -> {
                writeByte(7.toByte())
                val list = value as List<*>
                writeVInt(list.size)
                for (o in list) {
                    writeGenericValue(o)
                }
            }
            value is Array<*> -> {
                writeByte(8.toByte())
                val list = value as Array<*>
                writeVInt(list.size)
                for (o in list) {
                    writeGenericValue(o)
                }
            }
            value is Map<*, *> -> {
                if (value is LinkedHashMap<*, *>) {
                    writeByte(9.toByte())
                } else {
                    writeByte(10.toByte())
                }
                @Suppress("UNCHECKED_CAST")
                val map = value as Map<String, Any?>
                writeVInt(map.size)
                for ((k, v) in map) {
                    writeString(k)
                    writeGenericValue(v)
                }
            }
            type == Byte::class.javaObjectType || type == java.lang.Byte::class.java -> {
                writeByte(11.toByte())
                writeByte(value as Byte)
            }
            type == Date::class.java -> {
                writeByte(12.toByte())
                writeLong((value as Date).time)
            }
            value is BytesBuffer -> {
                writeByte(14.toByte())
                writeVInt(value.length())
                writeBytes(value)
            }
            type == Short::class.javaObjectType || type == java.lang.Short::class.java -> {
                writeByte(16.toByte())
                writeShort(value as Short)
            }
            else -> throw IOException("Can't write type [$type]")
        }
    }

    companion object {
        private val ZERO: Byte = 0
        private val ONE: Byte = 1
        private const val COPY_BUFFER_SIZE = 16384
    }
}

