        this._offset = offset
        this.hash = 0
    }

    fun length(length: Int) {
        this._length = length
        this.hash = 0
    }

    fun ignoreCase() {
        if (!ignoreCase) {
            this.ignoreCase = true
            hash = 0
        }
    }

    fun verifyCase() {
        if (ignoreCase) {
            this.ignoreCase = false
            hash = 0
        }
    }

    fun isIgnoreCase(): Boolean = ignoreCase

    override fun hashCode(): Int {
        if (hash > 0) return hash
        var h = 0
        var off = _offset
        for (i in 0 until _length) {
            var ch = array[off++].code
            ch = toUpperChar(ch).code
            h = 31 * h + ch
        }
        hash = h
        return h
    }

    fun trim(): CharVector {
        while (_length > 0 && array[_offset] == ' ') {
            _offset++
            _length--
        }
        while (_length > 0 && array[_offset + _length - 1] == ' ') {
            _length--
        }
        hash = 0
        return this
    }

    override fun toString(): String {
        return if (_length > 0) {
            String(array, _offset, _length)
        } else {
