                if (ignoreCase || other.ignoreCase) {
                    for (i in 0 until _length) {
                        if (toUpperChar(get(i).code) != toUpperChar(other.get(i).code)) {
                            return false
                        }
                    }
                } else {
                    for (i in 0 until _length) {
                        if (get(i) != other.get(i)) {
                            return false
                        }
                    }
