        val len1 = this._length
        val len2 = other.length
        val minlen = if (len1 < len2) len1 else len2
        for (cinx in 0 until minlen) {
            val c1 = this.get(cinx)
            val c2 = other[cinx]
            if (c1 != c2) {
                return if (c1 > c2) 1 else -1
            }
        }
        return when {
