package com.danawa.util

import org.json.JSONObject
import org.yaml.snakeyaml.Yaml
import java.io.File
import java.io.FileReader
import java.io.Reader
import java.util.Properties

class ResourceResolver {

    companion object {
        private const val PREFIX_FILE = "file:/"
        private const val SUFFIX_CLASS = ".class"
        private const val SUFFIX_JAR = ".jar!/"
        private const val SEPARATOR_PATH = "/"

        @JvmStatic
        fun getResourceRoot(cls: Class<*>): File? {
            var ret: File? = null
            val url = cls.getResource(cls.simpleName + SUFFIX_CLASS)
            var path = url!!.file
            if (path.startsWith(PREFIX_FILE)) {
                path = path.substring(PREFIX_FILE.length)
            }
            var cutIndex = path.indexOf(SUFFIX_JAR)
            if (cutIndex != -1) {
                path = path.substring(0, cutIndex + SUFFIX_JAR.length - 2)
                cutIndex = path.lastIndexOf(SEPARATOR_PATH)
                path = path.substring(0, cutIndex)
                if (File.separatorChar == '/') {
                    path = File.separatorChar + path
                }
                ret = File(path)
            } else {
                val pkg = cls.packageName
                path = path.substring(0, path.length - pkg.length - SEPARATOR_PATH.length
                        - cls.simpleName.length - SUFFIX_CLASS.length)
                if (File.separatorChar == '/') {
                    path = File.separatorChar + path
                }
                ret = File(path)
            }
            return ret
        }

        @JvmStatic
        fun readProperties(file: File): Properties? {
            var ret = Properties()
            var reader: Reader? = null
            try {
                reader = FileReader(file)
                ret.load(reader)
            } catch (e: Exception) {
                return null
            } finally {
                try { reader?.close() } catch (ignore: Exception) { }
            }
            return ret
        }

        @JvmStatic
        fun readYmlConfig(file: File): JSONObject? {
            var ret: JSONObject? = null
            var reader: Reader? = null
            try {
                reader = FileReader(file)
                val yaml = Yaml()
                @Suppress("UNCHECKED_CAST")
                ret = JSONObject(yaml.loadAs(reader, Map::class.java) as Map<*, *>)
            } catch (e: Exception) {
                ret = null
            } finally {
                try { reader?.close() } catch (ignore: Exception) { }
            }
            return ret
        }
    }
}

