        val cv = CharVector(keyword.toString().trim(), ignoreCase)
        if (cv.length() == 0) return
        val value = arrayOf<CharSequence>(cv)
        for (i in values!!.indices) {
            map[CharVector(values[i].toString(), ignoreCase)] = value
        }
    }
}

