    55→
    56→	public KoreanWordExtractor(ProductNameDictionary koreanDict) {
    57→		this(koreanDict, 20);
    58→	}
    59→
    60→	public KoreanWordExtractor(ProductNameDictionary koreanDict, int tabularSize) {
    61→		tabular = new PosTagProbEntry[tabularSize][];
    62→		// tabular 파싱 초기화.
    63→		for (int row = 0; row < tabular.length; row++) {
    64→			tabular[row] = new PosTagProbEntry[row + 2];
    65→		}
    66→		status = new int[tabularSize];
    67→		this.koreanDict = koreanDict;
    68→		josaSet = new HashSet<CharVector>();
    69→		String josaList = "은 는 이 가 을 를 에 과 와 의 로 만 께 에게 에서 으로 부터 라서 라고 께서 한테 처럼 같이 라는 하며 하고 까지 이라고 이라는 이라도 이라면 에서도 이기도";
    70→		String[] jl = josaList.split("\\s");
    71→		for (String j : jl) {
    72→			josaSet.add(new CharVector(j));
    73→		}
    74→		tabularStringer = new TabularStringer();
    75→		entryStringer = new EntryStringer();
    76→	}
