    89→
    90→	/*
    91→	 * 음절을 조합하여 사전에서 찾아준다. 찾은 단어와 tag는 table에 저장한다.
    92→	 */
    93→	private ExtractedEntry doSegment() {
    94→		CharVector cv = new CharVector(source, offset, length);
    95→		// 길이가 1~2 단어는 완전매칭이 아니면 UNK이다.
    96→		if (length == 1) {
    97→			// FIXME 나중엔 뺀다. extractor를 제일 먼저받을 것이기 때문..
    98→			// 조사이면 전체 조사로.
    99→			List<TagProb> tag = koreanDict.find(cv);
   100→			if (tag != null) {
   101→				return new ExtractedEntry(length - 1, length, tag.get(0), offset);
   102→			}
   103→			if (isDigit(cv)) {
   104→				return new ExtractedEntry(length - 1, length, TagProb.DIGIT, offset);
   105→			} else if (isSymbol(cv)) {
   106→				return new ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset);
   107→			}
   108→			return new ExtractedEntry(length - 1, length, TagProb.UNK, offset);
   109→		}
   110→		List<TagProb> tag = koreanDict.find(cv);
   111→		if (tag != null) {
   112→			return new ExtractedEntry(length - 1, length, tag.get(0), offset);
   113→		}
   114→		int start = length - 1;
   115→		for (int row = start; row >= 0; row--) {
   116→			for (int column = row + 1; column >= 1; column--) {
   117→				cv.init(offset + row - column + 1, column);
   118→				List<TagProb> tagList = null;
   119→				boolean isAlpha = false;
   120→				if (isDigit(cv)) {
   121→					// 무조건 셋팅.
   122→					tabular[row][column] = new PosTagProbEntry(TagProb.DIGIT);
   123→					status[row]++;
   124→				} else if (isSymbol(cv)) {
   125→					tabular[row][column] = new PosTagProbEntry(TagProb.SYMBOL);
   126→					status[row]++;
   127→				} else {
   128→					if (isAlpha(cv)) {
   129→						if (column == 1) {
   130→							tabular[row][column] = new PosTagProbEntry(TagProb.ALPHA);
   131→							/* 2019.3.28 @swsong ALPHA 는 분석발견이 아니라고 가정한다. */
   132→							continue;
   133→						}
   134→						// 길이가 2이상이면 사전에서 확인해본다.
   135→						isAlpha = true;
   136→					}
   137→					tagList = koreanDict.find(cv);
   138→					if (tagList != null) {
   139→						if (column == length) {
   140→							// 완전일치시
   141→							// logger.debug("Exact match {}", cv);
   142→							return new ExtractedEntry(row, column, tagList.get(0), offset);
   143→						}
   144→						PosTagProbEntry chainedEntry = null;
   145→						for (int i = 0; i < tagList.size(); i++) {
   146→							TagProb tagProb = tagList.get(i);
   147→							if (i == 0) {
   148→								chainedEntry = new PosTagProbEntry(tagProb);
   149→								tabular[row][column] = chainedEntry;
   150→							} else {
   151→								chainedEntry = chainedEntry.next(tagProb);
   152→							}
   153→						}
   154→						status[row]++;
   155→					} else {
   156→
   157→						if (isAlpha) {
   158→							// 영문자이면 null이 아닌 ALPHA로 셋팅한다.
   159→							tabular[row][column] = new PosTagProbEntry(TagProb.ALPHA);
   160→						} else {
   161→							tabular[row][column] = null;
   162→						}
   163→					}
   164→
   165→					if (column < 3) {
   166→						// 1글자가 조사인지.
   167→						if (josaSet.contains(cv)) {
   168→							PosTagProbEntry entry = new PosTagProbEntry(TagProb.JOSA);
   169→							if (tabular[row][column] == null) {
   170→								tabular[row][column] = entry;
   171→							} else {
   172→								entry.next = tabular[row][column];
   173→								tabular[row][column] = entry;
   174→							}
   175→							status[row]++;
   176→						}
   177→					}
   178→				}
   179→			}
   180→		}
   181→		return null;
   182→	}
   183→
   184→	// 유니코드 블럭인지 판단 (일부가 유니코드이면 유니코드 블럭으로 인식)
   185→	private boolean isUnicode(char[] buffer, int offset, int length) {
   186→		for (int inx = 0; inx < length; inx++) {
   187→			char ch = buffer[offset + inx];
   188→			if (ch > 127) {
   189→				return true;
   190→			}
   191→		}
   192→		return false;
   193→	}
   194→
   195→	// 단어가 전부숫자인지.
   196→	private boolean isDigit(CharVector cv) {
   197→		for (int i = 0; i < cv.length(); i++) {
   198→			char ch = cv.charAt(i);
   199→			if (ch >= '0' && ch <= '9') {
   200→				// 숫자면 다음을 본다.
   201→			} else {
   202→				return false;
   203→			}
   204→		}
   205→		return true;
   206→	}
   207→	
   208→	private boolean isAlpha(CharVector cv) {
   209→		for (int i = 0; i < cv.length(); i++) {
   210→			char ch = cv.charAt(i);
   211→			if ((ch >= 'a' && ch <= 'z') || ch >= 'A' && ch <= 'Z') {
   212→				// 다음을 본다.
   213→			} else {
   214→				return false;
   215→			}
   216→		}
   217→		return true;
   218→	}
   219→
   220→	private boolean isSymbol(CharVector cv) {
   221→		for (int i = 0; i < cv.length(); i++) {
   222→			int chInt = cv.charAt(i);
   223→			if (!Character.isLetterOrDigit(chInt)) {
   224→				// 다음을 본다.
   225→			} else {
   226→				return false;
   227→			}
   228→		}
   229→		return true;
   230→	}
   231→	
   232→	private void makeResult() {
   233→		int headRow = -1;
   234→		for (int row = length - 1; row >= 0; row--) {
   235→			if (status[row] > 0) {
   236→				// 분석결과가 존재하는지.
   237→				headRow = row;
   238→				break;
   239→			}
   240→		}
   241→
   242→		try {
   243→			if (headRow == -1) {
   244→				// 통째 미등록어.
   245→				addResult(new ExtractedEntry(length - 1, length, TagProb.UNK, offset));
   246→				return;
   247→			}
   248→			// 최초 char부터의 단어매칭이 없다면.
   249→			// 예를들어 "대한민국"분석시 "대한"만 사전에 있어서 "민국"은 결과가 없을경우.
   250→			if (headRow < length - 1) {
   251→				// 뒷부분을 미등록어로 처리한다. "대한(N)+민국(UNK)" 이 된다.
   252→				ExtractedEntry tail = new ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset);
   253→				connectAllTo(headRow, tail);
   254→			} else {
   255→				connectAllTo(headRow, null);
   256→			}
   257→			ExtractedEntry tail = null;
   258→			// logger.trace("Q:{}", queue);
   259→			while ((tail = queue.poll()) != null) {
   260→				// logger.trace("T:{}", tail);
   261→				int connectRow = tail.row() - tail.column();
   262→				if (status[connectRow] > 0) {
   263→					connectAllTo(connectRow, tail);
   264→				} else {
   265→					//
   266→					// TODO 앞에 붙을 단어가 없으면 row를 줄여가면서 존재하는 단어를 찾은후 connectAllTo를 붙인다.
   267→					//
   268→					connectTo(null, connectRow, -1, tail);
   269→				}
   270→			}
   271→		} catch (AnalyzeExceedException e) {
   272→			// 분석을 중단하고 탈출한다.
   273→			logger.debug("Analyze exceed : " + e.getMessage());
   274→		}
   275→	}
