   468→			
   469→			if (length > tabular.length) {
   470→				if (logger.isTraceEnabled()) {
   471→					logger.trace("CUT TABULAR SIZE : {}/ {} -> {}", length, new String(buffer, offset, length), new String(buffer, offset, tabular.length));
   472→				}
   473→				remnantOffset = tabular.length;
   474→				remnantLength = length - tabular.length;
   475→				length = tabular.length;
   476→			}
   477→		}
   478→		length = setInput0(buffer, offset, length);
   479→		return length;
   480→	}
   481→	
   482→	private int setInput0(char[] buffer, int offset, int length) {
   483→		this.source = buffer;
   484→		queue.clear();
   485→		result.clear();
   486→		// tabluar초기화.
   487→		this.offset = offset;
   488→		this.length = length;
   489→		// this.flushCount = 0;
   490→		fastResultFound = false;
   491→		return length;
   492→	}
   493→
   494→	public ExtractedEntry extract() {
   495→		tabularStringer.set(tabular, source, status, length, offset);
   496→		ExtractedEntry.source = source;
   497→		ExtractedEntry e = extract0();
   498→		ExtractedEntry last = e.last();
   499→		while (remnantLength > 0) {
   500→			int len = Math.min(tabular.length, remnantLength);
   501→			// 자른다.
   502→			setInput0(source, remnantOffset, len);
   503→			ExtractedEntry r = extract0();
   504→			if (r != null) {
   505→				// 잘못된 데이터. 순서적으로 나올수 없는 조합.
   506→				if (!(last.offset() + last.column() > r.offset())) {
   507→					last.next(r);
   508→					last = r.last();
   509→				}
   510→			}
   511→			remnantOffset += len;
   512→			remnantLength -= len;
   513→		}
   514→		return e;
   515→	}
   516→	
   517→	public ExtractedEntry extract0() {
   518→		ExtractedEntry e = doSegment();
   519→		if (e != null) {
   520→			return e;
   521→		}
   522→		// logger.trace(tabularStringer);
   523→		makeResult();
   524→		return getBestResult();
   525→	}
