   531→	private ExtractedEntry getHighResult() {
   532→		ExtractedEntry highEntry = null;
   533→		// logger.trace("RESULT:{}", result);
   534→		for (int k = 0; k < result.size(); k++) {
   535→			ExtractedEntry entry = result.get(k);
   536→			entry = finalCheck(entry);
   537→			if (entry == null) {
   538→				continue;
   539→			}
   540→			charVector.init(source, entry.offset(), entry.column());
   541→
   542→			if (highEntry == null) {
   543→				highEntry = entry;
   544→			} else {
   545→				if (isBetterThan(entry, highEntry)) {
   546→					// logger.trace("HIGHER:{} / {}", entry, highEntry);
   547→					highEntry = entry;
   548→				}
   549→			}
   550→		}
   551→		return highEntry;
   552→	}
   553→
   554→	public ExtractedEntry getBestResult() {
   555→		ExtractedEntry bestEntry = getHighResult();
   556→		if (bestEntry == null) {
   557→			// 통째 미등록어.
   558→			bestEntry = new ExtractedEntry(length - 1, length, TagProb.UNK, offset);
   559→			// logger.trace("UNKNOWN:{}", bestEntry);
   560→			return bestEntry;
   561→		}
   562→		return bestEntry;
   563→	}
   564→	
   565→	public int getTabularSize() {
   566→		return tabular.length;
   567→	}
   568→
   569→	/*
   570→	 * 두 PosTag간의 룰기반 접속문법검사
   571→	 */
   572→	protected boolean isConnectableByRule(TagProb headTagProb, int headRow, int headColumn, ExtractedEntry tail) {
   573→		//숫자끼리는 과분석된것이므로 연결해주지 않는다. 제일 긴 숫자가 사용하도록함.
   574→		if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
   575→			return false;
   576→		}
   577→		if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
   578→			return false;
   579→		}
   580→		if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
   581→			return false;
   582→		}
   583→		if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
   584→			// //은,이 와 는,가 일때 앞의 단어에 받침이 있는 지 확인.
   585→			if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
   586→				// "은 는 이 가 을 를 에 과 와 의 께";
   587→				char ch = source[offset + tail.row() - tail.column() + 1];
   588→				if (ch == '은' || ch == '이' || ch == '을' || ch == '과') {
   589→					if (!MorphUtil.hasLastElement(source[offset + headRow])) {
   590→						return false;
   591→					}
   592→				} else if (ch == '는' || ch == '가' || ch == '를' || ch == '와') {
   593→					if (MorphUtil.hasLastElement(source[offset + headRow])) {
   594→						return false;
   595→					}
   596→				}
   597→			}
   598→		}
   599→
   600→		// 두개 모두 한글자분석이면서 점수가 -12이하인것이 하나라도 있으면 통짜로 미등록어처리.
   601→		if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
   602→			if (tabular[tail.row()][tail.column() + headColumn] != null) {
   603→				// 단어가 존재하므로 버린다.
   604→				return false;
   605→			}
   606→		}
   607→		//3개연속 불허용.
   608→		return true;
   609→	}
   610→
   611→	/*
   612→	 * 두 엔트리를 접속시 합치거나 이어붙이는 로직을 구현한다.
   613→	 */
   614→	protected ExtractedEntry modifyAndConnect(TagProb tagProb, int row, int column, ExtractedEntry tail) {
   615→		ExtractedEntry newEntry = new ExtractedEntry(row, column, tagProb, offset);
   616→		return newEntry.next(tail);
   617→	}
   618→
   619→	private ExtractedEntry finalCheck(ExtractedEntry headEntry) {
   620→		// 첫글자 조사버림.
   621→		if (headEntry.posTag() == PosTag.J) {
   622→			return null;
   623→		}
   624→
   625→		int count = 0;
   626→		if (headEntry.entryCount() >= 2) {
   627→			ExtractedEntry current = headEntry;
   628→			while (current != null) {
   629→				if (current.column() > 1) {
   630→					break;
   631→				} else {
   632→					count++;
   633→				}
   634→				current = current.next();
   635→			}
   636→		}
   637→
   638→		if (count == headEntry.entryCount()) {
   639→			if (headEntry.last().posTag() == PosTag.J) {
   640→				return headEntry;
   641→			}
   642→			return null;
   643→		}
   644→		/*
   645→		 * 한글자 + GUESS(or -15미만) 결합은 합친다.
   646→		 */
   647→		return headEntry;
   648→	}
   649→	
   650→	/*
   651→	 * Best 결과를 뽑을때 사용하는 비교로직.
   652→	 */
   653→	protected boolean isBetterThan(ExtractedEntry entry, ExtractedEntry bestEntry) {
   654→		// 적게 잘린쪽이 우선.
   655→		// 2014-1-27 처리.. 이렇게 하면 무조건 항상 통 UNK가 나오게 된다.
   656→
   657→		// 점수가 큰쪽이 우선.
   658→		if (entry.totalScore() > bestEntry.totalScore()) {
   659→			return true;
   660→		}
   661→		return false;
   662→	}
