   620→
   621→                        currentEntry.length++;
   622→                        currentEntry.type = ALPHANUM;
   623→                        subQueue.remove(inx + 1);
   624→                    }
   625→                }
   626→            }
   627→
   628→            logger.trace("subQueue : {}", subQueue);
   629→            List<RuleEntry> tmpList = new ArrayList<>();
   630→
   631→            for (int inx = 0; inx < subQueue.size(); inx++) {
   632→                RuleEntry currentEntry = subQueue.get(inx);
   633→                if (currentEntry.type == SYMBOL) {
   634→                    char c = currentEntry.buf[currentEntry.start];
   635→                    if (c == '-' || c == '_' || c == '/') {
   636→                        // 모델명 중 영문 특수문자(-/) 숫자 조합인 경우 첫 영문 형태소를 제외한 모델명도 추출
   637→                        // 모델명이 모두 추가텀으로 바뀌어야 하기 때문에 이 쪽은 모두 추가텀으로 돌리도록 한다.
   638→                        // 2014.09.02 특수규칙. 영숫자가 번갈아 가며 나온 경우 (ALPHANUM) 와 겹치는 규칙이 있으므로
   639→                        // 체크해서 지워준다.
   640→                        if (!option.useForQuery()) {
   641→                            if (inx == 1 && inx + 2 < subQueue.size()) {
   642→                                RuleEntry prevEntry = subQueue.get(inx - 1);
   643→                                RuleEntry nextEntry = subQueue.get(inx + 1);
   644→                                RuleEntry nextNextEntry = subQueue.get(inx + 2);
   645→                                RuleEntry lastEntry = subQueue.get(subQueue.size() - 1);
   646→                                if (!(lastEntry.start == nextEntry.start && lastEntry.type == ALPHANUM)) {
   647→                                    if (prevEntry.length > 0 && nextEntry.start > (prevEntry.start + prevEntry.length)
   648→                                            && nextNextEntry.start == (nextEntry.start + nextEntry.length)
   649→                                            && prevEntry.type == ALPHA
   650→                                            && ((nextEntry.type == ALPHA && nextNextEntry.type == NUMBER)
   651→                                            || (nextEntry.type == NUMBER && nextNextEntry.type == ALPHA))) {
   652→                                        RuleEntry newEntry = new RuleEntry(nextEntry.buf, nextEntry.start, lastEntry.start + lastEntry.length - nextEntry.start, nextEntry.startOffset, lastEntry.endOffset, MODEL_NAME);
   653→                                        logger.trace("QUEUE : {}", subQueue);
   654→                                        logger.trace("NEW-ENTRY : {}", newEntry);
   655→                                        tmpList.add(newEntry);
   656→                                    }
   657→                                } else {
   658→                                    logger.trace("remove duplicated term : {}", lastEntry);
   659→                                }
   660→                            }
   661→                        }
   662→
   663→                        if (inx > 0 && inx + 1 < subQueue.size()) {
   664→                            RuleEntry prevEntry = subQueue.get(inx - 1);
   665→                            RuleEntry nextEntry = subQueue.get(inx + 1);
   666→                            if (!option.useForQuery()) {
   667→                                // 색인때에만
   668→                                // 모델명 중 숫자블럭 사이, 혹은 문자블럭 사이에 특수문자 가 있다면
   669→                                // 각각의 숫자, 혹은 문자 와 특수문자를 제거한 조합도 출력한다.
   670→                                int checkLevel = 0;
   671→                                if (nextEntry.startOffset == prevEntry.endOffset + 1) {
   672→                                    if (prevEntry.type == MODEL_NAME || prevEntry.type == ALPHANUM) {
   673→                                        if (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == ALPHANUM || nextEntry.type == MODEL_NAME) {
   674→                                            checkLevel = 2;
   675→                                        }
   676→                                    } else if (nextEntry.type == MODEL_NAME || nextEntry.type == ALPHANUM) {
   677→                                        if (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == ALPHANUM || prevEntry.type == MODEL_NAME) {
   678→                                            checkLevel = 2;
   679→                                        }
   680→                                    } else {
   681→                                        if (prevEntry.type == ALPHA || prevEntry.type == NUMBER) {
   682→                                            if (prevEntry.type == nextEntry.type) {
   683→                                                checkLevel = 3;
   684→                                            }
   685→                                        }
   686→                                    }
   687→                                }
   688→                                if (checkLevel == 2) {
   689→                                    // 앞단어 맨 뒤의 글자타입과 뒷단어 맨 첫번째의 글자타입이 같다면 수행
   690→                                    String lastCharTypeOfPrevEntry = getType(prevEntry.buf[prevEntry.start + prevEntry.length - 1]);
   691→                                    String firstCharTypeOfNextEntry = getType(nextEntry.buf[nextEntry.start]);
   692→                                    if (lastCharTypeOfPrevEntry == firstCharTypeOfNextEntry) {
   693→                                        // 같은 타입만 잘라낸다.
   694→                                        // 둘중 하나가 모델명 이었다면, 같은 타입의 부분만 잘라 내야 한다.
   695→                                        int newPrevEntryLength = 0;
   696→                                        for (int sinx = prevEntry.length; sinx > 0; sinx--) {
   697→                                            if (getType(prevEntry.buf[prevEntry.start + sinx - 1]) == lastCharTypeOfPrevEntry) {
   698→                                                newPrevEntryLength++;
   699→                                            } else {
   700→                                                break;
   701→                                            }
   702→                                        }
   703→                                        // 조정된 길이로 prevEntry 새로 셋팅.
   704→                                        RuleEntry tmpEntry = prevEntry.clone();
   705→                                        tmpEntry.start += (prevEntry.length - newPrevEntryLength);
   706→                                        tmpEntry.startOffset += (prevEntry.length - newPrevEntryLength);
   707→                                        tmpEntry.length = newPrevEntryLength;
   708→                                        tmpEntry.endOffset = tmpEntry.startOffset + newPrevEntryLength;
   709→                                        tmpEntry.type = lastCharTypeOfPrevEntry;
   710→                                        prevEntry = tmpEntry;
   711→
   712→                                        int newNextEntryLength = 0;
   713→                                        for (int sinx = 0; sinx < nextEntry.length; sinx++) {
   714→                                            if (getType(nextEntry.buf[nextEntry.start + sinx]) == firstCharTypeOfNextEntry) {
   715→                                                newNextEntryLength++;
   716→                                            } else {
   717→                                                break;
   718→                                            }
   719→                                        }
   720→                                        // 조정된 길이로 nextEntry 새로 셋팅.
   721→                                        RuleEntry tmpEntry2 = nextEntry.clone();
   722→                                        tmpEntry2.length = newNextEntryLength;
   723→                                        tmpEntry2.endOffset = tmpEntry2.startOffset + newNextEntryLength;
   724→                                        tmpEntry2.type = firstCharTypeOfNextEntry;
   725→                                        nextEntry = tmpEntry2;
   726→                                        checkLevel = 3;
   727→                                    }
   728→                                }
   729→                                if (checkLevel == 3) {
   730→                                    // 원본변형이 일어나기 때문에 버퍼는 따로 잡아 주어야 한다.
   731→                                    RuleEntry clone = prevEntry.clone();
   732→                                    char[] buf = new char[prevEntry.length + nextEntry.length];
   733→                                    System.arraycopy(prevEntry.buf, prevEntry.start, buf, 0, prevEntry.length);
   734→                                    System.arraycopy(nextEntry.buf, nextEntry.start, buf, prevEntry.length, nextEntry.length);
   735→                                    clone.buf = buf;
   736→                                    clone.start = 0;
   737→                                    clone.length = buf.length;
   738→                                    clone.startOffset = prevEntry.startOffset;
   739→                                    clone.endOffset = nextEntry.endOffset;
   740→                                    logger.trace("TRANS-MERGE:{} / {} / {}", clone, currentEntry, prevEntry);
   741→                                    tmpList.add(clone);
   742→                                }
   743→                            }
   744→                        }
   745→                    }
   746→                    // 개별 특수문자는 모두 제거한다.
   747→                    subQueue.remove(inx);
   748→                    inx--;
   749→                } else if (currentEntry.type == UNIT_ALPHA) {
   750→                    // 단위명이었지만 규칙에 의해 모델명으로 전환되는 경우.
   751→                    // 단위명과 숫자를 구분해준다.
   752→                    logger.trace("subList:{}{}", "", currentEntry.subEntry);
   753→                    if (currentEntry.subEntry != null && currentEntry.subEntry.size() > 0) {
   754→                        RuleEntry e1 = currentEntry.subEntry.remove(0);
   755→                        tmpList.add(e1);
   756→                        currentEntry.start += e1.length;
   757→                        currentEntry.length -= e1.length;
   758→                        currentEntry.type = ALPHA;
   759→                    } else {
   760→                        currentEntry.type = ALPHANUM;
   761→                    }
   762→                    currentEntry.synonym = null;
   763→                } else if (currentEntry.type == ALPHA) {
   764→                    // 강제분해 등으로 붙지 못한 영문자 끼리 이어준다.
   765→                    if (inx + 1 < subQueue.size()) {
   766→                        RuleEntry e1 = subQueue.get(inx + 1);
   767→                        if (e1.startOffset == currentEntry.endOffset + 1 && e1.type == ALPHA) {
   768→                            currentEntry.length += e1.length;
   769→                            currentEntry.endOffset = e1.endOffset;
   770→                            subQueue.remove(inx + 1);
   771→                        }
   772→                    }
   773→                }
   774→            }
   775→
   776→            logger.trace("subQueue : {}", subQueue);
   777→
   778→            if (subQueue.size() > 2) {
   779→                RuleEntry currentEntry = subQueue.get(0);
   780→                RuleEntry nextEntry = subQueue.get(1);
   781→                logger.trace("TERM:{}/{}", nextEntry.start, nextEntry.length);
   782→                String finalType = getType(nextEntry.buf[nextEntry.start + nextEntry.length - 1]);
   783→                // 모델명 맨 앞의 두 바이트가 타입이 틀리고 뒤에 기호가 나오면 붙여준다.
   784→                if (nextEntry.start == currentEntry.start + currentEntry.length &&
   785→                        currentEntry.length == 1 && nextEntry.length == 1 && finalType == SYMBOL
   786→                        && ((currentEntry.type == NUMBER && nextEntry.type == ALPHA)
   787→                        || (currentEntry.type == ALPHA && nextEntry.type == NUMBER))) {
   788→                    subQueue.remove(1);
   789→                    currentEntry.length += nextEntry.length;
   790→                    currentEntry.endOffset = currentEntry.startOffset + currentEntry.length + nextEntry.length;
   791→                    currentEntry.type = MODEL_NAME;
   792→                }
   793→            }
   794→
   795→            if (!option.useForQuery()) {
   796→                // 추가 텀 추출
   797→                exportByTriGram(subQueue, tmpList);
   798→                // 단위명 추가 텀 추출
   799→                exportUnitGram(subQueue, tmpList, unitDictionary);
   800→            }
   801→
   802→            if (tmpList.size() > 0) {
   803→                subQueue.addAll(tmpList);
   804→            }
   805→            ////////////////////////////////////////////////////////////////////////////////
   806→            Collections.sort(subQueue);
   807→        }
   808→    }
   809→
   810→    private static void exportByTriGram(List<RuleEntry> subQueue, List<RuleEntry> tmpList) {
   811→        Iterator<RuleEntry> iter = subQueue.iterator();
   812→        RuleEntry currentEntry = null;
   813→        RuleEntry nextEntry = null;
   814→
   815→        while (iter.hasNext()) {
   816→            if (currentEntry == null) {
   817→                currentEntry = iter.next();
   818→            }
   819→
   820→            RuleEntry nextNextEntry;
   821→
   822→            if (currentEntry.length == 1 && ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) || currentEntry.type == NUMBER)) {
   823→                // 다음 엔트리를 불러온다
   824→                if (iter.hasNext() && nextEntry == null) {
   825→                    nextEntry = iter.next();
   826→
   827→                    // 현재와 다음 엔트리를 비교 및 결합한다
   828→                    if (isConnected(currentEntry, nextEntry)) {
   829→                        combineNextEntry(tmpList, currentEntry, nextEntry, ALPHANUM);
   830→                    }
   831→                }
   832→
   833→                // 현재와 다음, 다다음 엔트리를 비교 및 결합한다
   834→                if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || nextEntry.type == NUMBER)) {
   835→                    if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) && nextEntry.type == NUMBER))) {
   836→                        // 다다음 엔트리를 불러온다
   837→                        if (iter.hasNext()) {
   838→                            nextNextEntry = iter.next();
   839→
   840→                            // 다다음 엔트리까지 확인해서 결합한다
   841→                            if (isConnected(currentEntry, nextEntry) && isConnected(nextEntry, nextNextEntry)) {
   842→                                if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
   843→                                    combineNextNextEntry(tmpList, currentEntry, nextEntry, nextNextEntry, ALPHANUM);
   844→                                }
   845→                            } else if (isConnected(nextEntry, nextNextEntry)) {
   846→                                if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
   847→                                    combineNextNextEntry(tmpList, nextEntry, nextNextEntry, ALPHANUM);
   848→                                }
   849→                            }
   850→
   851→                            // 읽은 곳까지 기록한다
   852→                            currentEntry = nextEntry;
   853→                            nextEntry = nextNextEntry;
   854→                        }
   855→                    } else {
   856→                        // 영문, 숫자 1 바이트가 아니라면 다음 엔트리로 이동한다.
   857→                        currentEntry = nextEntry;
   858→                        nextEntry = null;
   859→                    }
   860→                } else if (iter.hasNext()) {
   861→                    // 영문, 숫자 1 바이트가 아니라면 다음 엔트리로 이동한다.
   862→                    currentEntry = nextEntry;
   863→                    nextEntry = null;
   864→                }
   865→            } else if (iter.hasNext()) {
   866→                // 영문, 숫자 1 바이트가 아니라면 다음 엔트리로 이동한다.
   867→                currentEntry = iter.next();
   868→            }
   869→        }
   870→    }
