package com.danawa.search.analysis.product.rule

import com.danawa.search.analysis.dict.*
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.search.analysis.product.AnalyzerOption
import com.danawa.search.analysis.product.ProductNameTokenizer.*
import org.apache.logging.log4j.LogManager

abstract class Rule(
    protected var entry: Entry,
    protected val fullExtract: Boolean,
    protected var option: AnalyzerOption
) {
    protected var extractor: KoreanWordExtractor? = null

    protected var unitDictionary: SetDictionary? = null
    protected var spaceDictionary: SpaceDictionary? = null
    protected var unitSynonymDictionary: SynonymDictionary? = null
    protected var userDictionary: SetDictionary? = null
    protected var compoundDictionary: CompoundDictionary? = null
    protected var stopDictionary: SetDictionary? = null

    abstract fun apply(queue: MutableList<RuleEntry>)

    protected fun containsDictionary(cv: com.danawa.util.CharVector): Boolean {
        if (extractor!!.dictionary().find(cv) != null ||
            userDictionary!!.contains(cv) ||
            (option.useForQuery() && compoundDictionary!!.containsKey(cv))) {
            return true
        }
        return false
    }

    protected fun isConnected(prevEntry: RuleEntry, entry: RuleEntry): Boolean {
        return entry.start == prevEntry.start + prevEntry.length
    }

    protected fun isNotConnected(prevEntry: RuleEntry, entry: RuleEntry): Boolean {
        return entry.start != prevEntry.start + prevEntry.length
    }

    protected fun isEntryType(entry: RuleEntry, targetType: String?): Boolean {
        return entry.type == targetType
    }

    protected fun isEntryType(entry: RuleEntry, type1: String?, type2: String?): Boolean {
        return entry.type == type1 || entry.type == type2
    }

    protected fun isEntryType(entry: RuleEntry, type1: String?, type2: String?, type3: String?): Boolean {
        return entry.type == type1 || entry.type == type2 || entry.type == type3
    }

    protected fun isEntryType(entry: RuleEntry, type1: String?, type2: String?, type3: String?, type4: String?): Boolean {
        return entry.type == type1 || entry.type == type2 || entry.type == type3 || entry.type == type4
    }

    protected fun isEntryType(entry: RuleEntry, type1: String?, type2: String?, type3: String?, type4: String?, type5: String?): Boolean {
