                                entry.endOffset -= 1
                                entry.type = charType
                                subQueue.clear()
                                processed = true
                            } else if ((charType === SYMBOL) && (nextCharType === ALPHA || nextCharType === NUMBER)) {
                                entry.start++
                                entry.startOffset++
                                entry.length--
                                entry.type = nextCharType
                                subQueue.clear()
                                processed = true
                            } else if (charType !== nextCharType &&
