package com.danawa.search.analysis.highlight

import org.apache.lucene.index.IndexReader
import org.apache.lucene.index.PrefixCodedTerms
import org.apache.lucene.index.Term
import org.apache.lucene.search.BooleanQuery
import org.apache.lucene.search.ConstantScoreQuery
import org.apache.lucene.search.IndexSearcher
import org.apache.lucene.search.Query
import org.apache.lucene.search.QueryVisitor
import org.apache.lucene.search.ScoreMode
import org.apache.lucene.search.TermQuery
import org.apache.lucene.search.Weight
import org.apache.lucene.search.BooleanClause.Occur
import org.apache.lucene.util.Accountable
import org.apache.lucene.util.ArrayUtil
import org.apache.lucene.util.BytesRef
import org.apache.lucene.util.BytesRefBuilder

import java.io.IOException
import java.util.SortedSet

class TermHighlightingQuery : Query, Accountable {

    private val termData: PrefixCodedTerms

    constructor(field: String, terms: Collection<BytesRef>) {
        val sortedTerms = terms.toTypedArray()
        val sorted = terms is SortedSet<*> && (terms as SortedSet<BytesRef>).comparator() == null
        if (!sorted) {
            ArrayUtil.timSort(sortedTerms)
        }
        val builder = PrefixCodedTerms.Builder()
        var previous: BytesRefBuilder? = null
        for (term in sortedTerms) {
            if (previous == null) {
                previous = BytesRefBuilder()
            } else if (previous.get() == term) {
                continue
            }
            builder.add(field, term)
            previous.copyBytes(term)
        }
        termData = builder.finish()
    }

    constructor(field: String, vararg terms: BytesRef) : this(field, terms.toList())

    @Throws(IOException::class)
    override fun rewrite(searcher: IndexSearcher): Query {
        val threshold = minOf(BOOLEAN_REWRITE_TERM_COUNT_THRESHOLD, IndexSearcher.getMaxClauseCount())
        if (termData.size() <= threshold) {
            val bq = BooleanQuery.Builder()
            val iterator = termData.iterator()
            var term = iterator.next()
            while (term != null) {
                bq.add(TermQuery(Term(iterator.field(), BytesRef.deepCopyOf(term))), Occur.SHOULD)
                term = iterator.next()
            }
            return ConstantScoreQuery(bq.build())
        }
        return super.rewrite(searcher)
    }

    override fun visit(visitor: QueryVisitor) {}
    override fun equals(other: Any?): Boolean = false
    override fun hashCode(): Int = 0
    override fun toString(defaultField: String?): String? = null
    override fun ramBytesUsed(): Long = 0
    override fun getChildResources(): Collection<Accountable>? = null

    @Throws(IOException::class)
    override fun createWeight(searcher: IndexSearcher, scoreMode: ScoreMode, boost: Float): Weight? = null

    companion object {
        const val BOOLEAN_REWRITE_TERM_COUNT_THRESHOLD = 16
    }
}

