import org.elasticsearch.rest.RestRequest.Method.GET
import org.elasticsearch.rest.RestRequest.Method.POST

class ProductNameAnalysisAction : BaseRestHandler() {

    private var indexingThread: DanawaBulkTextIndexer? = null
    private var migratingThread: FastcatMigrateIndexer? = null

    override fun routes(): List<Route> {
        return Collections.unmodifiableList(Arrays.asList(
            Route(GET, "$BASE_URI/{action}"),
            Route(POST, "$BASE_URI/{action}"),
            Route(GET, "$BASE_URI/"),
            Route(POST, "$BASE_URI/")))
    }

    override fun getName(): String {
        return "rest_handler_product_name_analysis"
    }

    @Throws(IOException::class)
    override fun prepareRequest(request: RestRequest, client: NodeClient): RestChannelConsumer {
        val action = request.param("action")
        val buffer = StringWriter()
        val builder = JSONWriter(buffer)

        if (ACTION_TEST == action) {
            testAction(request, client, builder)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_RELOAD_DICT == action) {
            reloadDictionary()
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_INFO_DICT == action) {
            builder.`object`().key("action").value(action)
            infoDictionary(request, client, builder)
            builder.endObject()
        } else if (ACTION_FIND_DICT == action) {
            builder.`object`().key("action").value(action)
            findDictionary(request, client, builder)
            builder.endObject()
        } else if (ACTION_RESTORE_DICT == action) {
            restoreDictionary(request, client)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_COMPILE_DICT == action) {
            compileDictionary(request, client)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_FULL_INDEX == action) {
            val count = bulkIndex(request, client)
            builder.`object`().key("action").value(action)
            if (count > 0) {
                builder.key("working").value("true").key("count").value(count)
            } else {
                builder.key("working").value("false")
            }
            builder.endObject()
        } else if (ACTION_FASTCAT_INDEX == action) {
            val count = fastcatIndex(request, client)
            builder.`object`().key("action").value(action)
            if (count > 0) {
                builder.key("working").value("true").key("count").value(count)
            } else {
                builder.key("working").value("false")
            }
            builder.endObject()
        } else if (ACTION_ANALYZE_TEXT == action) {
            analyzeTextAction(request, client, builder)
        } else if (ACTION_SEARCH == action) {
            search(request, client, builder)
        } else if (ACTION_BUILD_QUERY == action) {
            buildQuery(request, client, builder)
        } else if (ACTION_ANALYZE_MULTI_PARAMS == action) {
            builder.`object`()
            analyzeMultiParamsAction(request, client, builder)
            builder.endObject()
        } else if (ACTION_SYNONYM_LIST == action) {
            builder.`object`()
            getSynonymListAction(request, client, builder)
            builder.endObject()
        } else if (ACTION_SEARCH_KEYWORD == action) {
            makeSearchKeyword(request, client, builder)
        } else if (ACTION_CHECK_ENABLE == action) {
            builder.`object`().key("loaded").value(getDictionary() != null)
            builder.endObject()
        }
        return RestChannelConsumer { channel ->
            channel.sendResponse(RestResponse(RestStatus.OK, CONTENT_TYPE_JSON, BytesArray(buffer.toString().toByteArray(StandardCharsets.UTF_8))))
        }
    }

    private fun parseRequestBody(request: RestRequest): JSONObject {
        var ret = JSONObject()
        try {
            ret = JSONObject(JSONTokener(request.content().utf8ToString()))
        } catch (ignore: Exception) { }
        return ret
    }

    fun testAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        logger.debug("TEST-ACTION")
    }

    private fun distribute(client: NodeClient, action: String, body: JSONObject, selfDist: Boolean) {
        val localNodeId = client.localNodeId
        val infoRequest = NodesInfoRequest()
        infoRequest.clear()
            .addMetrics(NodesInfoMetrics.Metric.JVM.metricName())
            .addMetrics(NodesInfoMetrics.Metric.OS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PROCESS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.HTTP.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PLUGINS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.INDICES.metricName())

        try {
            val response = client.admin().cluster().nodesInfo(infoRequest).get()
            val nodes = response.nodes
            for (node in nodes) {
                if (!selfDist && localNodeId == node.node.id) {
                    continue
                }
                var hasPlugin = false
                val address = node.getInfo(HttpInfo::class.java).address().publishAddress()
                val plugins = node.getInfo(PluginsAndModules::class.java).pluginInfos
                for (info in plugins) {
                    hasPlugin = info.descriptor().classname == AnalysisProductNamePlugin::class.java.name
                    if (hasPlugin) break
                }
                if (hasPlugin) {
                    logger.debug("NODE: {}:{}", address.address, address.port)
                    doRestRequest(address.address, address.port, action, body)
                }
            }
        } catch (e: Exception) {
            logger.error("", e)
        }
    }

    private fun doRestRequest(address: String, port: Int, action: String, body: JSONObject): String {
        val sb = StringBuilder()
        var con: HttpURLConnection? = null
        var ostream: OutputStream? = null
        var reader: BufferedReader? = null
        try {
            val url = "http://$address:$port$BASE_URI/$action"
            logger.debug("SEND REQUEST {}", url)
            con = URL(url).openConnection() as HttpURLConnection
            con.requestMethod = "POST"
            con.setRequestProperty("Content-Type", "application/json")
            con.doOutput = true
            ostream = con.outputStream
            ostream.write(body.toString().toByteArray())
            ostream.flush()
            val responseCode = con.responseCode
            if (responseCode == HttpURLConnection.HTTP_CREATED) {
                logger.trace("RESPONSE:{}", responseCode)
                reader = BufferedReader(InputStreamReader(con.inputStream))
                var rl: String?
                while (reader.readLine().also { rl = it } != null) {
                    sb.append(rl).append("\r\n")
                }
                logger.trace("RESPONSE:{}", sb)
            }
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { ostream?.close() } catch (ignore: Exception) { }
            try { reader?.close() } catch (ignore: Exception) { }
        }
        return sb.toString()
    }

    private fun analyzeTextAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var text = request.param("text", "")
        var detail = request.paramAsBoolean("detail", true)
        var useForQuery = request.paramAsBoolean("useForQuery", true)
        var useSynonym = request.paramAsBoolean("useSynonym", true)
        var useStopword = request.paramAsBoolean("useStopword", false)
        var useFullString = request.paramAsBoolean("useFullString", true)
        var test = false
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            text = jparam.optString("text", "")
            detail = jparam.optBoolean("detail", true)
            useForQuery = jparam.optBoolean("useForQuery", true)
            useSynonym = jparam.optBoolean("useSynonym", true)
            useStopword = jparam.optBoolean("useStopword", false)
            useFullString = jparam.optBoolean("useFullString", true)
            test = jparam.optBoolean("test", false)
        }

        var stream: TokenStream? = null
        try {
            stream = ProductNameAnalyzerProvider.getAnalyzer(text, useForQuery, useSynonym, useStopword, useFullString, false)
            analyzeTextDetailWriteJSON(client, text, stream, index, detail, writer, useForQuery)
        } finally {
            try { stream?.close() } catch (ignore: Exception) { }
        }

        if (test) {
            distribute(client, ACTION_TEST, jparam, true)
        }
    }

    private fun analyzeMultiParamsAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        logger.debug("multi-params Action")
        val index = ES_DICTIONARY_INDEX
        val useForQuery = false
        val useSynonym = true
        val useStopword = false
        val useFullString = true

        val analyzeMap: MutableMap<String, String> = HashMap()
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            for (key in jparam.keySet()) {
                analyzeMap[key] = jparam.optString(key, "")
            }
        } else {
            try {
                for (key in request.params().keys) {
                    if (key == "action" || key == "pretty") continue
                    analyzeMap[key] = URLDecoder.decode(request.param(key, ""), "UTF-8")
                }
            } catch (e: UnsupportedEncodingException) {
                logger.error("UnsupportedEncodingException Catched !!! >>>> \n" + e.message)
                writer.key("success").value(false)
                logger.debug("error >>> {}", e)
            }
        }

        var stream: TokenStream? = null
        writer.key("result").`object`()
        try {
            for (key in analyzeMap.keys) {
                val value = analyzeMap[key]
                logger.debug("key : {} :::::: value : {}", key, value)
                stream = ProductNameAnalyzerProvider.getAnalyzer(value!!, useForQuery, useSynonym, useStopword, useFullString, false)
                val list = analyzeMultiParamsText(null, value, stream, index, useForQuery)
                if (list.size != 0) {
                    writer.key(key).array()
                    for (item in list) {
                        writer.value(item)
                    }
                    writer.endArray()
                }
                stream.close()
            }
        } catch (ignore: Exception) {
            writer.endObject()
            writer.key("success").value(false)
            logger.debug("exception >>> {}", ignore)
            logger.error("Exception Catched !!! >>>> \n" + ignore.message)
        } finally {
            writer.endObject()
            writer.key("success").value(true)
        }
    }

    private fun reloadDictionary() {
        if (contextStore.containsKey(ProductNameDictionary.PRODUCT_NAME_DICTIONARY)) {
            ProductNameDictionary.reloadDictionary()
        }
    }

    private fun compileDictionary(request: RestRequest, client: NodeClient) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var type = request.param("type", null as String?)
        var exportFile = request.paramAsBoolean("exportFile", false)
        var distribute = request.paramAsBoolean("distribute", false)
        var host = request.param("host", null as String?)
        var port = request.paramAsInt("port", 9200)
        var username = request.param("username", null as String?)
        var password = request.param("password", null as String?)

        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            type = jparam.optString("type", null)
            exportFile = jparam.optBoolean("exportFile", false)
            distribute = jparam.optBoolean("distribute", false)
            host = jparam.optString("host", null)
            port = jparam.optInt("port", 9200)
            username = jparam.optString("username", null)
            password = jparam.optString("password", null)
        } else {
            jparam.put("index", index)
            jparam.put("type", type)
            jparam.put("exportFile", exportFile)
            jparam.put("distribute", distribute)
            jparam.put("host", host)
            jparam.put("port", port)
            jparam.put("username", username)
            jparam.put("password", password)
        }

        val repo: DictionarySource
        if (host != null && "" != host) {
            val remoteNodeClient = RemoteNodeClient(client.settings(), client.threadPool(), ES_DICTIONARY_INDEX, host, port, username, password)
            repo = DictionarySource(remoteNodeClient, index)
        } else {
            repo = DictionarySource(client, index)
        }

        ProductNameDictionary.compileDictionary(client, repo, type, exportFile)
        ProductNameDictionary.reloadDictionary()

        if (distribute) {
            jparam.put("distribute", false)
            distribute(client, ACTION_COMPILE_DICT, jparam, false)
        }
    }

    private fun infoDictionary(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var host = request.param("host", null as String?)
        var port = request.paramAsInt("port", 9200)
        var username = request.param("username", null as String?)
        var password = request.param("password", null as String?)

        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            host = jparam.optString("host", null)
            port = jparam.optInt("port", 9200)
            username = jparam.optString("username", null)
            password = jparam.optString("password", null)
        }

        val searchMap = SearchUtil.searchData(client, ".dsearch_dict_apply")
        val remoteNodeClient = RemoteNodeClient(client.settings(), client.threadPool(), ES_DICTIONARY_INDEX, host, port, username, password)

        val productNameDictionary = getDictionary()!!
        builder
            .key("dictionary").array()
            .`object`()
            .key(ES_DICT_FIELD_TYPE).value("SYSTEM")
            .key("class").value(TagProbDictionary::class.java.simpleName)
            .key("count").value(productNameDictionary.size())
            .key("label").value(productNameDictionary.label())
            .key("seq").value(productNameDictionary.seq())
            .key("ignoreCase").value(productNameDictionary.ignoreCase())
            .key("tokenType").value("NONE")
            .endObject()
        val dictionaryMap = productNameDictionary.dictionaryMap
        val keySet = dictionaryMap.keys
        for (key in keySet) {
            val typeStr = key.uppercase()
            val sourceDictionary = dictionaryMap[key]!!
            val info = ProductNameDictionary.getDictionaryInfo(sourceDictionary)
            val indexCount: Long
            if (host != null && "" != host) {
                indexCount = SearchUtil.count(remoteNodeClient, index, QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, typeStr))
            } else {
                indexCount = SearchUtil.count(client as Client, index, QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, typeStr))
            }

            val id = typeStr.lowercase()
            var count = 0
            var appliedTime = ""
            var updatedTime = ""

            if (searchMap[id] != null) {
                count = searchMap[id] as Int
            }
            if (searchMap[id + "_appliedTime"] != null) {
                appliedTime = searchMap[id + "_appliedTime"] as String
            }
            if (searchMap[id + "_updatedTime"] != null) {
                updatedTime = searchMap[id + "_updatedTime"] as String
            }

            builder.`object`()
                .key(ES_DICT_FIELD_TYPE).value(typeStr)
                .key("class").value(sourceDictionary.javaClass.simpleName)
                .key("dictType").value(sourceDictionary.type().name)
                .key("ignoreCase").value(sourceDictionary.ignoreCase())
                .key("tokenType").value(if (sourceDictionary.tokenType() == null) "NONE" else sourceDictionary.tokenType())
                .key("label").value(sourceDictionary.label())
                .key("seq").value(sourceDictionary.seq())
                .key("id").value(key)
                .key("updatedTime").value(updatedTime)
                .key("appliedTime").value(appliedTime)
                .key("count").value(count)
                .key("indexCount").value(indexCount)

            if (info[1] != 0) {
                builder.key("words").value(info[1])
            }
            builder.endObject()
        }
        builder.endArray()
    }

    private fun findDictionary(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var word = request.param("word", "")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            word = jparam.optString("word", "")
        }

        val productNameDictionary = getDictionary()!!
        val keySet = productNameDictionary.dictionaryMap.keys

        builder.key("result").array()

        val tagProbs = productNameDictionary.find(CharVector.valueOf(word))
        if (tagProbs != null) {
            for (inx in tagProbs.indices) {
                val tagProb = tagProbs[inx]
                builder.`object`()
                    .key(ES_DICT_FIELD_TYPE).value("SYSTEM")
                    .key(ES_DICT_FIELD_KEYWORD).value(word)
                    .key("posTag").value(tagProb.posTag())
                    .key("prob").value(tagProb.prob())
                    .endObject()
            }
        }
        for (type0 in keySet) {
            val type = type0.uppercase()
            val query = QueryBuilders.boolQuery()
                .must(QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type))
                .must(QueryBuilders.boolQuery()
                    .should(QueryBuilders.matchQuery(ES_DICT_FIELD_KEYWORD, word))
                    .should(QueryBuilders.matchQuery(ES_DICT_FIELD_VALUE, word))
                )
            val result = SearchUtil.search(client as Client, index, query, null, null, 0, -1, true, null)
            while (result.hasNext()) {
                val data = result.next()
                val keyword = CharVector.valueOf(data[ES_DICT_FIELD_KEYWORD])
                val value = CharVector.valueOf(data[ES_DICT_FIELD_VALUE])
                val id = CharVector.valueOf(data[ES_DICT_FIELD_ID])
                builder.`object`()
                builder.key(ES_DICT_FIELD_TYPE).value(type)
                if (keyword != null && keyword.length() > 0) {
                    builder.key(ES_DICT_FIELD_KEYWORD).value(keyword)
                }
                if (value != null && value.length() > 0) {
                    builder.key(ES_DICT_FIELD_VALUE).value(value)
                }
                if (id != null && id.length() > 0) {
                    builder.key(ES_DICT_FIELD_ID).value(id)
                }
                builder.endObject()
            }
        }
        builder.endArray()
    }

