        var stream: TokenStream? = null
        try {
            stream = ProductNameAnalyzerProvider.getAnalyzer(text, true, synonym, stopWord, true, false)
            expansionKeyword(text, stream, writer)
        } finally {
            try { stream?.close() } catch (ignore: Exception) { }
        }
    }

    private fun getSynonymListAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        var keyword = ""
        val useForQuery = true
        val useSynonym = true
        val useStopword = false
        val useFullString = true

