    70→		BufferedReader reader = null;
    71→		BufferedWriter writer = null;
    72→		File file = null;
    73→		BulkRequestBuilder builder = null;
    74→		long time = System.currentTimeMillis();
    75→		try {
    76→			logger.trace("SEND REQUEST {}", url);
    77→			int total = start + length;
    78→
    79→			if (path != null && !"".equals(path) && (file = new File(path)) != null && file.getParentFile().exists()) {
    80→				writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file), enc));
    81→			}
    82→
    83→			if (client != null) { builder = client.prepareBulk(); }
    84→
    85→			for (int sinx = start; sinx < total; sinx += length) {
    86→				con = (HttpURLConnection) new URL(url + "&sn=" + sinx + "&ln=" + length).openConnection();
    87→				con.setRequestMethod("GET");
    88→				int responseCode = con.getResponseCode();
    89→				logger.trace("RESPONSE:{}", responseCode);
    90→				if (responseCode == HttpURLConnection.HTTP_OK) {
    91→					reader = new BufferedReader(new InputStreamReader(con.getInputStream()));
    92→					JSONTokener tokener = new JSONTokener(reader);
