    }

    @Throws(Exception::class)
    private fun filterMap(map: Map<String, Any>): Map<String, Any> {
        val mutableMap = map.toMutableMap()
        for (key in mutableMap.keys) {
            fieldValue(mutableMap, key, mutableMap[key].toString())
        }
        return mutableMap
    }

    @Throws(Exception::class)
    private fun fieldValue(source: MutableMap<String, Any>, key: String, value: String) {
        if ("" == key) {
            // skip
        } else if ("REGISTERDATE" == key) {
            if (value.isNotEmpty()) {
