            }
        } else {
            source[key] = value
        }
        logger.trace("ROW:{} / {}", key, value)
    }

    override fun run() {
        _running = true
        _count = 0
        migrateFastcat()
        _running = false
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(FastcatMigrateIndexer::class.java)

