package com.danawa.search.index

import java.io.ByteArrayInputStream
import java.nio.charset.StandardCharsets

import com.danawa.search.analysis.product.ProductNameTokenizer

import org.apache.logging.log4j.LogManager
import org.apache.lucene.analysis.TokenStream
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute
import org.apache.lucene.analysis.tokenattributes.ExtraTermAttribute
import org.apache.lucene.analysis.tokenattributes.SynonymAttribute
import org.apache.lucene.analysis.tokenattributes.TypeAttribute
import org.elasticsearch.common.io.stream.NamedWriteableRegistry
import org.elasticsearch.xcontent.NamedXContentRegistry
import org.elasticsearch.xcontent.XContentParser
import org.elasticsearch.xcontent.json.JsonXContent
import org.elasticsearch.xcontent.DeprecationHandler
import org.elasticsearch.index.query.BoolQueryBuilder
import org.elasticsearch.index.query.BoostingQueryBuilder
import org.elasticsearch.index.query.MatchPhraseQueryBuilder
import org.elasticsearch.index.query.MatchQueryBuilder
import org.elasticsearch.index.query.MultiMatchQueryBuilder
import org.elasticsearch.index.query.QueryBuilder
import org.elasticsearch.index.query.QueryBuilders
import org.elasticsearch.index.query.QueryStringQueryBuilder
import org.elasticsearch.index.query.RangeQueryBuilder
import org.elasticsearch.index.query.SimpleQueryStringBuilder
import org.elasticsearch.index.query.TermQueryBuilder
import org.elasticsearch.index.query.TermsQueryBuilder
import org.elasticsearch.index.query.TermsSetQueryBuilder
import org.elasticsearch.index.query.WrapperQueryBuilder
import org.elasticsearch.index.query.functionscore.FunctionScoreQueryBuilder
import org.elasticsearch.plugins.SearchPlugin
import org.elasticsearch.search.fetch.subphase.highlight.HighlightBuilder
import org.elasticsearch.search.sort.SortBuilder
import org.json.JSONArray
import org.json.JSONObject

class DanawaSearchQueryBuilder {

    var SEARCH_CONTENT_REGISTRY: NamedXContentRegistry? = null

    init {
        init()
    }

    private fun registerQueryBuilder(
        spec: SearchPlugin.QuerySpec<*>,
        namedWriteables: MutableList<NamedWriteableRegistry.Entry>,
        namedXContents: MutableList<NamedXContentRegistry.Entry>
    ) {
        namedWriteables.add(
            NamedWriteableRegistry.Entry(
                QueryBuilder::class.java, spec.name.preferredName, spec.reader
            )
        )
        namedXContents.add(
            NamedXContentRegistry.Entry(
                QueryBuilder::class.java, spec.name
            ) { p, _ -> spec.parser.fromXContent(p) }
        )
    }

    fun init() {
        val writables = mutableListOf<NamedWriteableRegistry.Entry>()
        val xcontents = mutableListOf<NamedXContentRegistry.Entry>()
        registerQueryBuilder(SearchPlugin.QuerySpec(MatchQueryBuilder.NAME, ::MatchQueryBuilder, MatchQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(MultiMatchQueryBuilder.NAME, ::MultiMatchQueryBuilder, MultiMatchQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(MatchPhraseQueryBuilder.NAME, ::MatchPhraseQueryBuilder, MatchPhraseQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(QueryStringQueryBuilder.NAME, ::QueryStringQueryBuilder, QueryStringQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(BoostingQueryBuilder.NAME, ::BoostingQueryBuilder, BoostingQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(BoolQueryBuilder.NAME, ::BoolQueryBuilder, BoolQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(RangeQueryBuilder.NAME, ::RangeQueryBuilder, RangeQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(WrapperQueryBuilder.NAME, ::WrapperQueryBuilder, WrapperQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(FunctionScoreQueryBuilder.NAME, ::FunctionScoreQueryBuilder, FunctionScoreQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(SimpleQueryStringBuilder.NAME, ::SimpleQueryStringBuilder, SimpleQueryStringBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(TermsSetQueryBuilder.NAME, ::TermsSetQueryBuilder, TermsSetQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(TermQueryBuilder.NAME, ::TermQueryBuilder, TermQueryBuilder::fromXContent), writables, xcontents)
        registerQueryBuilder(SearchPlugin.QuerySpec(TermsQueryBuilder.NAME, ::TermsQueryBuilder, TermsQueryBuilder::fromXContent), writables, xcontents)
        SEARCH_CONTENT_REGISTRY = NamedXContentRegistry(xcontents)
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(DanawaSearchQueryBuilder::class.java)

        @JvmField
        val INSTANCE = DanawaSearchQueryBuilder()

        const val AND = "AND"
        const val OR = "OR"
        const val SHOULD = "should"
        const val MUST = "must"
        const val BOOL = "bool"
        const val MATCHPHRASE = "match_phrase"
        const val MULTIMATCH = "multi_match"
        const val ANALYZER = "analyzer"
        const val QUERY = "query"
        const val FIELDS = "fields"
        const val SLOPE = "slope"
        const val WHITESPACE = "whitespace"

        @JvmStatic
        fun parseQuery(source: String): QueryBuilder? {
            var ret: QueryBuilder? = null
            try {
                val parser: XContentParser = JsonXContent.jsonXContent
                    .createParser(
                        INSTANCE.SEARCH_CONTENT_REGISTRY,
                        DeprecationHandler.IGNORE_DEPRECATIONS,
                        ByteArrayInputStream(source.toByteArray(StandardCharsets.UTF_8))
                    )
                parser.nextToken()
                ret = parser.namedObject(QueryBuilder::class.java, parser.currentName(), null)
            } catch (e: Exception) {
                logger.error("", e)
            }
            return ret
        }

        @JvmStatic
        fun parseSortSet(source: String): List<SortBuilder<*>>? {
            var ret: List<SortBuilder<*>>? = null
            try {
                val parser: XContentParser = JsonXContent.jsonXContent.createParser(
                    NamedXContentRegistry.EMPTY,
                    DeprecationHandler.IGNORE_DEPRECATIONS,
                    ByteArrayInputStream(source.toByteArray(StandardCharsets.UTF_8))
                )
                parser.nextToken()
                ret = SortBuilder.fromXContent(parser)
            } catch (e: Exception) {
                logger.error("", e)
            }
            return ret
        }

        @JvmStatic
        fun parseHighlight(source: String): HighlightBuilder? {
            var ret: HighlightBuilder? = null
            try {
                val parser: XContentParser = JsonXContent.jsonXContent.createParser(
                    NamedXContentRegistry.EMPTY,
                    DeprecationHandler.IGNORE_DEPRECATIONS,
                    ByteArrayInputStream(source.toByteArray(StandardCharsets.UTF_8))
                )
                parser.nextToken()
                ret = HighlightBuilder.fromXContent(parser)
            } catch (e: Exception) {
                logger.error("", e)
            }
            return ret
        }

        @JvmStatic
        fun buildAnalyzedQuery(
            stream: TokenStream, fields: Array<String>, totalIndex: String,
            boostMap: Map<String, Float>, views: List<String>?,
            highlightTerms: MutableList<String>?, explain: JSONObject?, analyzer: String
        ): QueryBuilder? {
            var ret: QueryBuilder? = null
            val termAttr = stream.addAttribute(CharTermAttribute::class.java)
            val typeAttr = stream.addAttribute(TypeAttribute::class.java)
            val synAttr = stream.addAttribute(SynonymAttribute::class.java)
            val extAttr = stream.addAttribute(ExtraTermAttribute::class.java)
            try {
                stream.reset()
                val mainQuery = QueryBuilders.boolQuery()
                ret = mainQuery
                var mainExplain: JSONObject? = null
                if (explain != null) {
                    mainExplain = JSONObject()
                    mainExplain.put(AND, JSONArray())
                    explain.put(AND, mainExplain)
                }
                while (stream.incrementToken()) {
                    val term = termAttr.toString()
                    val type = typeAttr.type()
                    logger.trace("TOKEN:{} / {}", term, type)
                    highlightTerms?.add(term)

                    var termExplain: JSONArray? = null
                    if (explain != null) {
                        termExplain = JSONArray()
                        termExplain.put(term)
                    }
                    var synonyms: List<CharSequence>? = null
                    var termQuery: QueryBuilder = QueryBuilders.multiMatchQuery(term, *fields).fields(boostMap).analyzer(analyzer)

                    if (synAttr != null) {
                        synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
                            logger.trace("SYNONYM [{}] = {}", term, synonyms)
                            termQuery = synonymQuery(termQuery, synonyms, fields, boostMap, termAttr, typeAttr, synAttr, extAttr, highlightTerms, termExplain, analyzer)
                        }
                    }
                    if (extAttr != null && extAttr.size() > 0) {
                        logger.trace("EXTRA [{}] = {}", term, extAttr)
                        termQuery = extraQuery(termQuery, fields, boostMap, termAttr, typeAttr, synAttr, extAttr, highlightTerms, termExplain, analyzer)
                    }

                    if (ProductNameTokenizer.FULL_STRING != type) {
                        mainQuery.must().add(termQuery)
                        if (explain != null) {
                            if (termExplain != null && termExplain.length() > 1) {
                                val subExplain = JSONObject()
                                subExplain.put(OR, termExplain)
                                mainExplain!!.optJSONArray(AND).put(subExplain)
                            } else {
                                mainExplain!!.optJSONArray(AND).put(term)
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                logger.error("", e)
            } finally {
                try { stream.close() } catch (ignore: Exception) { }
            }
            return ret
        }

        @JvmStatic
        fun buildAnalyzedJSONQuery(
            stream: TokenStream, fields: Array<String>, totalIndex: String, analyzer: String
        ): JSONObject {
            var ret = JSONObject()
            val termAttr = stream.addAttribute(CharTermAttribute::class.java)
            val typeAttr = stream.addAttribute(TypeAttribute::class.java)
            val synAttr = stream.addAttribute(SynonymAttribute::class.java)
            val extAttr = stream.addAttribute(ExtraTermAttribute::class.java)
            try {
                stream.reset()
                val mainQuery = JSONObject()
                ret = mainQuery
                while (stream.incrementToken()) {
                    val term = termAttr.toString()
                    val type = typeAttr.type()
                    logger.trace("TOKEN:{} / {}", term, type)

                    var synonyms: List<CharSequence>? = null
                    var termQuery = JSONObject()
                    termQuery.put(
                        MULTIMATCH,
                        JSONObject().put(ANALYZER, analyzer)
                            .put(QUERY, term)
                            .put(FIELDS, fields)
                    )

                    if (synAttr != null) {
                        synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
                            logger.trace("SYNONYM [{}] = {}", term, synonyms)
                            termQuery = synonymJSONQuery(termQuery, synonyms, fields, termAttr, typeAttr, synAttr, extAttr, analyzer)
                        }
                    }
                    if (extAttr != null && extAttr.size() > 0) {
                        logger.trace("EXTRA [{}] = {}", term, extAttr)
                        termQuery = extraJSONQuery(termQuery, fields, termAttr, typeAttr, synAttr, extAttr, analyzer)
                    }

                    if (ProductNameTokenizer.FULL_STRING != type) {
                        appendJSONQuery(mainQuery, MUST, termQuery)
                    }
                }
            } catch (e: Exception) {
                logger.error("", e)
            } finally {
                try { stream.close() } catch (ignore: Exception) { }
            }
            return ret
        }

        @JvmStatic
        private fun appendJSONQuery(mainQuery: JSONObject, mode: String, termQuery: JSONObject) {
            val boolQuery = if (mainQuery.has(BOOL)) {
                mainQuery.getJSONObject(BOOL)
            } else {
                JSONObject().also { mainQuery.put(BOOL, it) }
            }
            val termQueries = if (boolQuery.has(mode)) {
                boolQuery.getJSONArray(mode)
            } else {
                JSONArray().also { boolQuery.put(mode, it) }
            }
            termQueries.put(termQuery)
        }

        @JvmStatic
        fun fullTermQuery(totalIndex: String, boostMap: Map<String, Float>, phrase: String, slop: Int): QueryBuilder {
            val ret = QueryBuilders.boolQuery()
            ret.should().add(
                QueryBuilders.matchPhraseQuery(totalIndex, phrase).boost(0f).slop(slop).analyzer(WHITESPACE)
            )
            return ret
        }

        @JvmStatic
        fun phraseQuery(fields: Array<String>, boostMap: Map<String, Float>, phrase: String, slop: Int, analyzer: String): QueryBuilder {
            val ret = QueryBuilders.boolQuery()
            val split = phrase.split(" ")
            for (word in split) {
                ret.must().add(QueryBuilders.multiMatchQuery(word, *fields).fields(boostMap).analyzer(analyzer))
            }
            return ret
        }

        @JvmStatic
        fun phraseJSONQuery(fields: Array<String>, phrase: String, slop: Int, analyzer: String): JSONObject {
            val ret = JSONObject()
            val split = phrase.split(" ")
            for (word in split) {
                val termQuery = JSONObject()
                termQuery.put(
                    MULTIMATCH,
                    JSONObject().put(ANALYZER, analyzer)
                        .put(QUERY, word)
                        .put(FIELDS, fields)
                )
                appendJSONQuery(ret, MUST, termQuery)
            }
            return ret
        }

        @JvmStatic
        fun synonymQuery(
            query: QueryBuilder, synonyms: List<CharSequence>, fields: Array<String>,
            boostMap: Map<String, Float>, termAttr: CharTermAttribute, typeAttr: TypeAttribute,
            synAttr: SynonymAttribute, extAttr: ExtraTermAttribute,
            highlightTerms: MutableList<String>?, explain: JSONArray?, analyzer: String
        ): QueryBuilder {
            val subQuery = QueryBuilders.boolQuery()
            subQuery.should().add(query)
            for (sinx in synonyms.indices) {
                val synonym = synonyms[sinx].toString()
                explain?.put(synonym)
                if (synonym.indexOf(" ") == -1) {
                    subQuery.should().add(QueryBuilders.multiMatchQuery(synonym, *fields).fields(boostMap).analyzer(analyzer))
                } else {
                    subQuery.should().add(phraseQuery(fields, boostMap, synonym, 3, analyzer))
                }
            }
            return subQuery
        }

        @JvmStatic
        fun synonymJSONQuery(
            query: JSONObject, synonyms: List<CharSequence>, fields: Array<String>,
            termAttr: CharTermAttribute, typeAttr: TypeAttribute,
            synAttr: SynonymAttribute, extAttr: ExtraTermAttribute, analyzer: String
        ): JSONObject {
            val subQuery = JSONObject()
            appendJSONQuery(subQuery, SHOULD, query)
            for (sinx in synonyms.indices) {
                val synonym = synonyms[sinx].toString()
                if (synonym.indexOf(" ") == -1) {
                    val termQuery = JSONObject()
                    termQuery.put(
                        MULTIMATCH,
                        JSONObject().put(ANALYZER, analyzer)
                            .put(QUERY, synonym)
                            .put(FIELDS, fields)
                    )
                    appendJSONQuery(subQuery, SHOULD, termQuery)
                } else {
                    appendJSONQuery(subQuery, SHOULD, phraseJSONQuery(fields, synonym, 3, analyzer))
                }
            }
            return subQuery
        }

        @JvmStatic
        fun extraQuery(
            query: QueryBuilder, fields: Array<String>, boostMap: Map<String, Float>,
            termAttr: CharTermAttribute, typeAttr: TypeAttribute,
            synAttr: SynonymAttribute, extAttr: ExtraTermAttribute,
            highlightTerms: MutableList<String>?, explain: JSONArray?, analyzer: String
        ): QueryBuilder {
            var synonyms: List<CharSequence>?
            var ret: QueryBuilder = query
            if (extAttr != null && extAttr.size() > 0) {
                var termExplain: JSONArray? = null
                if (explain != null) {
                    termExplain = JSONArray()
                    explain.put(JSONObject().put(AND, termExplain))
                }
                val subQuery = QueryBuilders.boolQuery()
                val termIter = extAttr.iterator()
                while (termIter.hasNext()) {
                    val term = termIter.next()
                    val type = typeAttr.type()
                    highlightTerms?.add(term)
                    synonyms = synAttr.synonyms
                    if (synonyms == null || synonyms.isEmpty()) {
                        subQuery.must().add(QueryBuilders.multiMatchQuery(term, *fields).fields(boostMap).analyzer(analyzer))
                        termExplain?.put(term)
                    } else {
                        val subExplain = JSONArray()
                        subExplain.put(term)
                        termExplain?.put(JSONObject().put(OR, subExplain))
                        val termQuery = QueryBuilders.multiMatchQuery(term, *fields)
                        subQuery.must().add(
                            synonymQuery(termQuery, synonyms, fields, boostMap, termAttr, typeAttr, synAttr, extAttr, highlightTerms, subExplain, analyzer)
                        )
                    }
                    logger.trace("a-term:{} / type:{} / synonoym:{}", term, type, synonyms)
                }
                val parent = QueryBuilders.boolQuery()
                parent.should().add(query)
                parent.should().add(subQuery)
                ret = parent
            }
            return ret
        }

        @JvmStatic
        fun extraJSONQuery(
            query: JSONObject, fields: Array<String>,
            termAttr: CharTermAttribute, typeAttr: TypeAttribute,
            synAttr: SynonymAttribute, extAttr: ExtraTermAttribute, analyzer: String
        ): JSONObject {
            var synonyms: List<CharSequence>?
            var ret: JSONObject = query
            if (extAttr != null && extAttr.size() > 0) {
                val subQuery = JSONObject()
                val termIter = extAttr.iterator()
                while (termIter.hasNext()) {
                    val term = termIter.next()
                    val type = typeAttr.type()
                    synonyms = synAttr.synonyms
                    val termQuery = JSONObject()
                    termQuery.put(
                        MULTIMATCH,
                        JSONObject().put(ANALYZER, analyzer)
                            .put(QUERY, term)
                            .put(FIELDS, fields)
                    )

                    if (synonyms == null || synonyms.isEmpty()) {
                        appendJSONQuery(subQuery, MUST, termQuery)
                    } else {
                        appendJSONQuery(subQuery, MUST, synonymJSONQuery(termQuery, synonyms, fields, termAttr, typeAttr, synAttr, extAttr, analyzer))
                    }
