                appendJSONQuery(parent, SHOULD, subQuery)
                appendJSONQuery(parent, SHOULD, query)
                ret = parent
            }
            return ret
        }

        @JvmStatic
        fun andQuery(vararg queries: QueryBuilder): QueryBuilder {
