package com.danawa.search.util

import org.apache.logging.log4j.LogManager
import org.elasticsearch.action.search.SearchRequest
import org.elasticsearch.common.settings.Settings
import org.elasticsearch.core.TimeValue
import org.elasticsearch.index.query.MatchQueryBuilder
import org.elasticsearch.threadpool.ThreadPool
import org.json.JSONObject

import java.io.BufferedReader
import java.io.IOException
import java.io.InputStreamReader
import java.net.HttpURLConnection
import java.net.URL
import java.nio.charset.StandardCharsets
import java.util.Base64

class RemoteNodeClient : Any {

    private val index: String
    private val host: String
    private val port: Int
    private var username: String? = null
    private var password: String? = null
    private val url: String
    private val settings: Settings
    private val threadPool: ThreadPool

    constructor(settings: Settings, threadPool: ThreadPool, index: String, host: String, port: Int) {
        this.settings = settings
        this.threadPool = threadPool
        this.host = host
        this.port = port
        this.url = "http://$host:$port"
        this.index = index
    }

    constructor(settings: Settings, threadPool: ThreadPool, index: String, host: String, port: Int, username: String, password: String)
        : this(settings, threadPool, index, host, port) {
        this.username = username
        this.password = password
    }

    fun search(request: SearchRequest): JSONObject? {
        var co: HttpURLConnection? = null
        var reader: BufferedReader? = null
        try {
            var scroll = ""
            val scrollTime = request.scroll()
            if (scrollTime != null) {
                scroll = "scroll=$scrollTime"
            }
            logger.info("dictionary Remote Search . {}, username: {}", url, username)
            co = URL("$url/$index/_search?$scroll").openConnection() as HttpURLConnection
            co.requestMethod = "POST"
            co.setRequestProperty("Content-Type", "application/json")
            if (username != null && username!!.isNotEmpty()) {
                val token = String(
                    Base64.getEncoder().encode("$username:$password".toByteArray(StandardCharsets.UTF_8))
                ).replace("==", "")
                co.setRequestProperty("Authorization", "Basic $token")
            }
            co.doOutput = true
            co.doInput = true
            co.outputStream.write(request.source().toString().toByteArray(StandardCharsets.UTF_8))
            co.outputStream.flush()
            reader = BufferedReader(InputStreamReader(co.inputStream))
            val sb = StringBuilder()
            var rl = reader.readLine()
            while (rl != null) {
                sb.append(rl)
                rl = reader.readLine()
            }
            return JSONObject(sb.toString())
        } catch (e: IOException) {
            logger.warn("", e)
            return null
        } finally {
            try { reader?.close() } catch (ignore: Exception) { }
            co?.disconnect()
        }
    }

    fun searchScroll(scrollId: String, scrollTime: TimeValue): JSONObject? {
        var co: HttpURLConnection? = null
        var reader: BufferedReader? = null
        try {
            logger.info("dictionary Remote searchScroll . {}, username: {}", url, username)
            val param = """{ "scroll_id":"$scrollId", "scroll":"$scrollTime"}"""
            val paramData = param.toByteArray(StandardCharsets.UTF_8)

            co = URL("$url/_search/scroll").openConnection() as HttpURLConnection
