   393→		public ReflectHelper(String[] paths) throws Exception {
   394→			final List<URL> urlList = new ArrayList<URL>();
   395→			final FileFilter fileFilter = new FileFilter() {
   396→				@Override public boolean accept(File file) {
   397→					if (!file.exists()) { return false; }
   398→					if (file.isDirectory()) { file.listFiles(this); }
   399→					String path = file.getAbsolutePath();
   400→					if (path.endsWith(".jar")) {
   401→						try {
   402→							urlList.add(new URL("jar:file:" + path + "!/"));
   403→						} catch (Exception ignore) { }
   404→					}
   405→					return false;
   406→				}
   407→			};
   408→			for (String path : paths) {
   409→				new File(path).listFiles(fileFilter);
   410→			}
   411→			URL[] urls = new URL[urlList.size()];
   412→			urls = urlList.toArray(urls);
   413→			this.loader = new URLClassLoader(urls, Thread.currentThread().getContextClassLoader());
   414→			this.classMap = new HashMap<>();
   415→		}
