    class FilesReader(f: File) : FileFilter {
        private val files: MutableList<String> = mutableListOf()
        private var reader: BufferedReader? = null

        init {
            if (f.isDirectory) {
                f.listFiles(this)
            } else {
                files.add(f.absolutePath)
            }
        }

        @Throws(Exception::class)
        fun isAvail(): Boolean {
            return reader != null || files.isNotEmpty()
        }

        @Throws(Exception::class)
        fun readLine(): String? {
            var ret: String? = null
            if (reader != null) {
                ret = reader!!.readLine()
            }
            if (ret == null) {
                try { reader?.close() } catch (ignore: Exception) { }
                if (files.isNotEmpty()) {
                    reader = BufferedReader(FileReader(File(files.removeAt(0))))
                    ret = reader!!.readLine()
                } else {
                    reader = null
                }
            }
            return ret
        }

        @Throws(Exception::class)
        fun close() {
            try { reader?.close() } catch (ignore: Exception) { }
        }

        override fun accept(f: File): Boolean {
            if (f.isDirectory) {
                f.listFiles(this)
            } else {
                files.add(f.absolutePath)
            }
            return false
        }
    }

