        private const val DICT_FASTCATSEARCH = "DICT_FASTCATSEARCH"
        private const val DICT_DANAWASEARCH = "DICT_DANAWASEARCH"

        const val TRACE = 1
        const val DEBUG = 2
        const val INFO = 3
        const val WARNING = 4
        const val ERROR = 5

        private var CURRENT_LOG_LEVEL = DEBUG

        @JvmStatic
        fun ty(vararg types: Class<*>): Array<Class<*>> = arrayOf(*types)

        @JvmStatic
        fun ar(vararg args: Any?): Array<Any?> = arrayOf(*args)

        @JvmStatic
        fun st(vararg args: String): Array<String> = arrayOf(*args)

        @JvmStatic
        @Throws(Exception::class)
        fun log(type: Int, vararg args: Any?) {
            if (CURRENT_LOG_LEVEL > type) { return }
            if (args.isNotEmpty()) {
                if (args[0] is String) {
                    val p = mutableListOf<CharSequence>()
                    val a = mutableListOf<StringBuilder>()
                    var str = args[0].toString()
                    var pos = str.indexOf("{}")
                    while (pos != -1) {
                        val sb = StringBuilder()
                        p.add(str.substring(0, pos))
                        p.add(sb)
                        a.add(sb)
                        str = str.substring(pos + 2)
                        pos = str.indexOf("{}")
                    }
                    p.add(str)
                    for (inx in 1 until args.size) {
                        if (inx - 1 < a.size) {
                            a[inx - 1].append(args[inx].toString())
                        }
                    }
                    val sb = StringBuilder()
                    for (item in p) {
                        sb.append(item)
                    }
                    println(sb.toString())
                }
            }
        }

        @JvmStatic
        @Throws(Exception::class)
        fun main(arg: Array<String>) {
            if (arg.size < 2) {
                println("USAGE: Tester {{CMD}} {{ES_PLUGIN_PATH}} {{CONTENT}}")
                println("EX: Tester input C:/ES/plugins/analysis-product  분석기테스트")
                println("    Tester files C:/ES/plugins/analysis-product  C:/test/test.txt")
                System.exit(0)
            }
            val inst = Tester()
            inst.test(arg[0], arg[1], arg[2])
        }
